-- Add Hospital Church building governance standards to knowledge base

INSERT INTO knowledge_base (category, question, answer, keywords) VALUES
('building_governance', 'What are the facility rules and governance standards?', 'The signed Rental Agreement is the governing document. These standards exist to clarify expectations and protect shared assets. In any conflict, the contract controls. Compliance is mandatory for all tenants, guests, and volunteers.', 'governance rules contract compliance rental agreement'),

('facility_use', 'What are the rules for using the facility spaces?', 'Spaces must be used solely for approved purposes and within the scheduled time window. No structural changes, drilling, mounting, or alterations without written approval. Furniture and equipment may not be relocated between rooms without approval.', 'facility use space approved purpose structural changes furniture'),

('equipment_protection', 'What are the equipment handling rules?', 'Use only assigned equipment. No access to control rooms, racks, or technical closets without authorization. No food or drink near audio, video, lighting, or IT equipment. Do not unplug, re-route, or reconfigure any cables, power strips, cameras, microphones, speakers, thermostats, or control panels. Report all malfunctions immediately. Do not attempt repairs.', 'equipment protection handling cables control room authorization'),

('cleaning_standards', 'What are the cleaning requirements after using the facility?', 'Reset the room to pre-service condition before departure. Remove all trash and personal items. Replace liners as needed. Wipe down podiums, lecterns, chairs, tables, microphones, and touch surfaces. Sweep/mop visible debris in use areas. Restrooms used must be left clean and restocked where possible. If condition is unacceptable, a mandatory cleaning fee will be assessed per the contract.', 'cleaning standards reset room trash wipe sweep mop restroom cleaning fee'),

('damage_reporting', 'How do I report damage or incidents?', 'All damage or loss (even minor) must be reported within 24 hours via the designated reporting channel. Include photos, time, location, and a brief description. Tenant is financially responsible for damage beyond normal wear and tear, per the contract.', 'damage loss incident reporting photos responsibility 24 hours'),

('electrical_safety', 'What are the electrical and safety rules?', 'No extension cords, personal power strips, heaters, or unauthorized appliances. Do not overload outlets. Emergency exits, doors, and aisles must remain clear at all times. No open flames, incense, or fog/smoke devices.', 'electrical safety extension cords outlets emergency exits flames smoke'),

('hvac_thermostat', 'Can I adjust the thermostat?', 'Only authorized personnel may adjust thermostats. If adjustment is needed, submit a request through the tenant portal or notify the building point of contact.', 'hvac thermostat temperature adjustment authorized request'),

('sound_conduct', 'What are the sound and conduct standards?', 'Maintain respectful volume levels, especially during overlapping events. No profanity, offensive content, illegal activity, or disruptive conduct on premises.', 'sound volume conduct respectful profanity disruptive behavior'),

('security_access', 'What are the security and access rules?', 'Access is limited to approved individuals only. No subletting or key sharing. Doors must be secured upon exit. Any lost codes/cards/keys must be reported immediately and may incur a replacement fee.', 'security access keys codes cards subletting doors locked replacement fee'),

('liability_insurance', 'What about liability and insurance?', 'Tenant must maintain any required coverage outlined in the contract. The building owner/manager is not liable for personal property left on-site.', 'liability insurance coverage property left on-site'),

('violations_enforcement', 'What happens if I violate the standards?', 'Non-compliance may result in: written warning, assessed fines, loss of access privileges, or termination of tenancy, per contract terms.', 'violations enforcement warnings fines termination non-compliance'),

('event_booking', 'How do I book an event or additional service?', 'To book an event or request additional services for your upcoming service, please provide: the date needed, hours needed, which sanctuary you need to rent, and any special requirements. Our team will follow up with you regarding availability and invoicing.', 'event booking additional service date hours sanctuary rental invoice'),

('invoice_questions', 'I have questions about my invoice', 'For invoice questions or billing concerns, please provide your invoice number and specific questions. Our administrative team will follow up with you within 1-2 business days to address your concerns.', 'invoice billing questions payment concerns follow up');
